TLM.f("Sancti/02-24",{"officium":"S. Matthiæ Apostoli","rule":["ex C1;","Gloria","Credo","Prefatio=Apostolis"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1","sections":{"Introitus":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Oratio":[{"k":"text","la":"Deus qui beatum Matthíam Apostolórum tuórum collégio sociásti: tríbue quǽsumus; ut ejus interventióne, tua circa nos píetas semper víscera sentiámus"},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Act 1, 15-26"},{"k":"text","la":"In diébus illis exsúrgens Petrus in médio fratrum, dixit - erat autem turba hóminum simul, fere centum vigínti -: Viri fratres, opórtet impléri Scriptúram, quam prædíxit Spíritus Sanctus per os David de Juda, qui fuit dux eórum, qui comprehendérunt Jesum: qui connumerátus erat in nobis, et sortítus est sortem ministérii hujus. Et hic quidem possédit agrum de mercéde iniquitátis, et suspénsus crépuit médius: et diffúsa sunt ómnia víscera ejus. Et notum factum est ómnibus habitántibus Jerúsalem, ita ut appellarétur ager ille, lingua eórum, Hacéldama, hoc est ager sánguinis. Scriptum est enim in libro Psalmórum: Fiat commorátio eórum desérta, et non sit, qui inhábitet in ea: et episcopátum ejus accípiat alter. Opórtet ergo ex his viris, qui nobíscum sunt congregáti in omni témpore, quo intrávit et exívit inter nos Dóminus Jesus, incípiens a baptísmate Joánnis usque in diem, qua assúmptus est a nobis, testem resurrectiónis ejus nobíscum fíeri unum ex istis. Et statuérunt duos, Joseph qui vocabátur Bársabas, qui cognominátus est Justus, et Matthíam. Et orántes dixérunt: Tu, Dómine, qui corda nosti ómnium, osténde, quem elégeris ex his duóbus unum, accípere locum ministérii hujus et apostolátus, de quo prævaricátus est Judas, ut abíret in locum suum. Et dedérunt sortes eis, et cécidit sors super Matthíam, et annumerátus est cum úndecim Apóstolis."}],"Graduale":[{"k":"ref","la":"Ps 138:17-18"},{"k":"text","la":"Nimis honoráti sunt amíci tui, Deus: nimis confortátus est principatus eórum."},{"k":"text","la":"Dinumerábo eos, et super arénam multiplicabúntur.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 138:17-18"},{"k":"text","la":"Nimis honoráti sunt amíci tui, Deus: nimis confortátus est principatus eórum."},{"k":"text","la":"Dinumerábo eos, et super arénam multiplicabúntur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 11:25-30"},{"k":"text","la":"In illo témpore: Respóndens Jesus, dixit: Confíteor tibi, Pater, Dómine coeli et terræ, quia abscondísti hæc a sapiéntibus et prudéntibus, et revelásti ea párvulis. Ita, Pater: quóniam sic fuit plácitum ante te. Omnia mihi trádita sunt a Patre meo. Et nemo novit Fílium nisi Pater: neque Patrem quis novit nisi Fílius, et cui volúerit Fílius reveláre. Veníte ad me, omnes, qui laborátis et oneráti estis, et ego refíciam vos. Tóllite jugum meum super vos, et díscite a me, quia mitis sum et húmilis corde: et inveniétis réquiem animábus vestris. Jugum enim meum suáve est et onus meum leve."}],"Offertorium":[{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine, in omni progénie et generatióne."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, quas nómini tuo sacrándas offérimus, sancti Matthíæ Apóstoli tui prosequátur orátio: per quam nos expiári fácias et deféndi."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28"},{"k":"text","la":"Vos, qui secúti estis me, sedébitis super sedes, judicántes duódecim tribus Israël."}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut per hæc sancta, quæ súmpsimus, interveniénte beáto Matthía Apóstolo tuo, véniam consequámur et pacem."},{"k":"macro","name":"Per Dominum"}]},"hr":{"4ce2969ae90d1d66":{"t":"Ps 138, 17, Ps 138, 1-2\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","kn":"(Ps. 138, 17). Veoma častim prijatelje Tvoje, Bože, silno je utvrđeno kneževstvo njihovo. (Ps. 133, 1). Gospodine, Ti sj me kušao i spoznaoi; Tebi je poznat moj počinak i moje ustajanje. Slava Ocu . . . Veoma ...","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"001f3777d1366ef5":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženoga Matiju pridružio zboru svojih apostola, daj, molimo, da po njegovu zagovoru uvijek osjećamo na sebi tvoju ljubav, punu smilovanja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si blaženoga Matiju pridružio zboru svojih apostola, daj, molimo, da njegovim zagovorom vazda oćutimo na sebi Tvoju ljubav, punu smilovanja, po G. n.","knRef":"Kniewald 1942, str. 512–513 (snimka 257) (OCR)"},"71ce83ccbfd22bdd":{"t":"Dj 1, 15-26\nČitanje Djela apostolskih. U one dane ustade Petar među braćom (a bilo ih je na okupu oko sto dvadeset ljudi) i reče: »Treba, ljudi braćo, da se ispuni Pismo kako po Davidu proreče Duh Sveti Judi, vođi onih koji su uhvatili Isusa. On je bio u našem broju i zapade ga dio ove službe, a njivu steče kao plaću za zločin. Objesi se, puče po sredini i prosu mu se sva utroba. I saznali su za to svi stanovnici Jeruzalema tako da se ta njiva naziva njihovim jezikom Hakeldama, to jest njiva krvi. Pisano je u knjizi Psa–lama: Pust bio njihov stan i ne našao se nitko, koji bi u njemu stanovao, a njegovu službu neka uzme drugi! Zato treba da jedan od ovih ljudi koji su bili s nama sve vrijeme što je Gospodin Isus boravio među nama, od kada je od Ivanova krsta počeo, sve do dana kada se uzeo nad nas, bude s nama svjedokom njegova uskrsnuća;« I postaviše dvojicu: Josipa, koji se zvao Barsaba, s prezimenom Justo, i Matiju. I molili su: »Ti Gospodine, koji poznaješ srca svih, pokaži kojega si izabrao od ove dvojice da preuzme mjesto ove službe i apostolstva, o koje se ogriješio Juda, da otiđe na svoje mjesto.« I birali su ih kockama, i pade kocka na Matiju koji je bio pribrojen jedanaestorici apostola.","kn":"Čitanje djela apostolskih (1, 15-26). U one dane ustade Petar među braćom (a bilo je na okupu oko stodvadeset ljudi) i reče: Treba, ljudi braćo, da se ispuni Pismo, kako po Davidu proreče Duh Sveti o Judi, vođi onih, koji su uhvatili Isusa. On je bio u našem broju i zapade ga dio ove službe, a njivu steče kao plaću za zločin. Objesi se, puče po sredini i prosu . mu se sva utroba. I saznali su za to svi stanovnici Jeruzalema, tako da se ta njiva naziva njihovim jezikom Hakeldama, to jest njiva su S-r. Malija 2i. II, krvi. Jer je pisano u knjizi Psalama: Pust bio njihov stan i ne našao se nitko, koji bi u njemu stanovao, a njegovu službu neka uzme drugi!* Zato treba, da jedan od ovih ljudi, koji su bili s nama sve vrijeme, što je Gospodin Isus boravio među nama, od kada je od Ivanova krsta počeo sve do dana, kad se uze od nas, bude s nama svjedokom njegova uskrsnuća. I ipostaviše dvojicu: Josipa, koji se zvao Barsaba, s prezimenom Justo, 1 Maitiiju. I molili su: Ti Gospodine, koji poznaš srca svih, pokaži, kojega si izabrao od ove dvojice, da preuzme mjesto ove službe i apostolstva, o koje se ogriješio Juda, da otiđe na svoje mjesto. I birali su ih kockama, i pade kocka na Matiju, koji je bio pribrojen jedanaestorici apostola.","knRef":"Kniewald 1942, str. 512–513 (snimka 257) (OCR)"},"863eb6844b7fdd2d":{"t":"Ps 138, 17-18\nNada sve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove. Da ih brojim, ima ih više nego pijeska.\n\nPs 20, 3-4\nTi si mu ispunio želju njegova srca i nisi mu uskratio molbe njegovih usana. Pretekao si ga slatkim blagoslovom. Postavio si mu na glavu vijenac od dragog kamenja.","kn":"(Ps. 138). Veoma častim prijatelje Tvoje, Bože, silno je utvrđeno kneževstvo njihovo. Kad bih ih brojio, bilo bi ih više od pijeska u mom. Aleluja, aleluja. (Ps. 32). Radujte se, pravednici, u Gospodinu, pravima se dolikuje pohvala. Aleluja. Iza sedamdesetnice mjesto Aleluja; Zaviaka (Ps. 20, 3-4). Ti si mu ispunio želju njegova srca i nisi mu uskratio molbe njegovih usana. Predusreo si ga slatkim blagoslovom i njegovu si .glavu okrunio krunom dragoga kamenja,","knRef":"Kniewald 1942, str. 514–515 (snimka 258) (OCR)"},"bb0bd8107f5e0717":{"t":"Mt 11, 25-30\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Zahvaljujem ti, Oče, Gospodaru neba i zemlje jer si ovo sakrio mudrima i razumnima, a objavio malenima. Da, Oče, jer ti se svidjelo tako! Moj je Otac predao meni sve, i nitko ne pozna Sina nego Otac, niti tko pozna Oca nego Sin i komu Sin hoće da objavi. Dođite k meni svi koji ste umorni i opterećeni i ja ću vas okrijepiti. Uzmite na sebe moj jaram i učite se od mene jer sam ja krotka i ponizna srca i naći ćete pokoj svojim dušama. Jer je moj jaram sladak i moje breme lako.","kn":"t Slijedi sveto evanđelje po Mateju (11, 25-30). U ono vrijeme reče Isus: Hvalim, ti. Oče, Gospodaru neba i zemlje, jer si ovo. sakrio mudrima i razumnima. a objavio to malenima. Da, Oče, jer ti se svidjelo tako! Moj je Otac predao meni sve, i nitko ne pozna Sina nego Otac, niti tko pozna Oca nego Sin, i komu Sin hoće da objavi. Dođite k meni svi, koji ste umorni i opterećeni i ja ću vas okrijepiti. Uzmite na sebe moj jaram i učite se od mene, jer sam ja krotak i ponizan u srcu i naći ćete pokoj svojim dušama. Jer je moj jaram sladak i moje breme lako.","knRef":"Kniewald 1942, str. 476–477 (snimka 239) (OCR)"},"93805934ca9284fe":{"t":"Ps 44, 17-18\nPostavit ćeš ih za knezove nad svom zemljom. Spominjat će tvoje ime, Gospodine, u svakom pokoljenju i naraštaju.","kn":"(Ps. 44, 17). Postavit ćeš ih za knezove po svoj zemlji; spominjat će se imena Tvoga u svakom rodu i potomstvu.","knRef":"Kniewald 1942, str. 514–515 (snimka 258) (OCR)"},"f984214f0d4065c3":{"t":"Pratila, Gospodine, molitva svetog Matije, apostola tvoga, žrtve, koje ti prinosimo, te učini da se po njima oslobodimo i obranimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pratila, Gospodine, molitva sv. Matije, apostola Tvoga, žrtve, koje Ti prinosimo, da nas očiste i brane po G. n.","knRef":"Kniewald 1942, str. 514–515 (snimka 258) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"4379ab930a0e53cb":{"t":"Mt 19, 28\nVi koji ste pošli za mnom sjedit ćete na prijestoljima i suditi dvanaest plemena Izraelovih.","kn":"(Mt. 19, 28). Vi. koji ste slijedili mene, sjedit ćete na prijestolima sudeći dvanaest plemena Izraelovih,","knRef":"Kniewald 1942, str. 628–629 (snimka 315) (OCR)"},"c01719be302d7db5":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da zagovorom tvoga svetog apostola Matije po primljenim svetim otajstvima zadobijemo oproštenje i mir.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj’ molimo, svemogući Bože, da zagovorom Tvoga svetog apostola Matije primljenim otajstvima zadobljemo oproštenje i mir, po G. n.","knRef":"Kniewald 1942, str. 514–515 (snimka 258) (OCR)"}}});
